import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { useAuth } from "../../contexts/AuthContext"; // Контекст за автентикация
import { doc, getDoc } from "firebase/firestore"; // Firebase функции
import { db } from "../../config/firebaseConfig"; // Конфигурация на Firebase

export default function Details() {
    const [project, setProject] = useState(null);
    const [loading, setLoading] = useState(true); // Състояние за зареждане
    const { projectId } = useParams();
    const { admin } = useAuth();

    useEffect(() => {
        const fetchProjectDetails = async () => {
            try {
                const projectRef = doc(db, "projects", projectId);
                const projectSnap = await getDoc(projectRef);

                if (projectSnap.exists()) {
                    setProject(projectSnap.data());
                } else {
                    alert("Project not found!");
                }
            } catch (error) {
                console.error("Error fetching project details:", error);
                alert("Failed to fetch project details. Please try again.");
            } finally {
                setLoading(false); // Спиране на индикатора за зареждане
            }
        };

        fetchProjectDetails();
    }, [projectId]);

    if (loading) {
        return <p>Loading project details...</p>;
    }

    if (!project) {
        return <p>Project not found or an error occurred.</p>;
    }

    return (
        <div className="container-details">
            <header className="header-details">
                <h1 id="details-title">{project.title}</h1>
            </header>
            <main style={{ marginBottom: "30px" }}>
                <div className="project-image">
                    <img
                        src={project.img}
                        alt="Project Image"
                        style={{ maxWidth: "100%", height: "auto" }}
                    />
                </div>
                <div className="project-description">
                    <p id="desc">{project.description}</p>
                </div>
                {project.gitLink && (
                    <a href={project.gitLink} target="_blank" rel="noopener noreferrer">
                        GitHub Link
                    </a>
                )}
            </main>
            {Boolean(admin?.username) && (
                <div className="admin-actions">
                    <Link
                        className="readedMessage"
                        to={`/update/${projectId}`}
                        style={{ margin: "10px" }}
                    >
                        Edit
                    </Link>
                    <Link
                        className="readedMessage"
                        to={`/delete/${projectId}`}
                        style={{ margin: "10px" }}
                    >
                        Delete
                    </Link>
                </div>
            )}
        </div>
    );
}
